import site from "@/data/site.json";
import { REPO_DESCRIPTIONS } from "./content";

/* View-models derived from src/data/site.json (regenerated by `npm run refresh-data`).
   Only import this from server components; pass the slices down as props. */

export type PrStatus = "merged" | "open" | "closed";

export interface PrVM {
  title: string;
  url: string;
  number: number;
  repo: string;
  repoUrl: string;
  repoStars: number;
  owner: string;
  avatar: string;
  own: boolean;
  status: PrStatus;
  date: string;
  /** Display string for diff size; large diffs capped as "1k+". */
  size: string;
}

export interface RepoVM {
  name: string;
  description: string;
  url: string;
  homepage: string;
  language: string;
  languageColor: string | null;
  stars: number;
  updatedAt: string;
}

export interface CpVM {
  lc: {
    url: string;
    username: string;
    rating: number | null;
    badge: string | null;
    topPercentage: number | null;
    attended: number;
    solved: { all: number; easy: number; medium: number; hard: number };
    totals: { all: number; easy: number; medium: number; hard: number };
    history: { rating: number; date: string; contest: string }[];
  };
  cf: {
    url: string;
    handle: string;
    rating: number | null;
    maxRating: number | null;
    rank: string | null;
    maxRank: string | null;
    solved: number;
    contests: number;
    history: { rating: number; date: string; contest: string }[];
  };
}

export interface ActivityVM {
  total: number;
  commits: number;
  pullRequests: number;
  privateContributions: number;
  start: string;
  end: string;
  /** weeks × 7 days of [date, count] (first week may be partial) */
  weeks: [string, number, number][][];
}

const fmtSize = (add: number, del: number) => {
  const cap = (n: number) => (n >= 1000 ? "1k+" : String(n));
  if (add + del >= 1000) return "1k+ lines";
  return `+${cap(add)} −${cap(del)}`;
};

export function getPrs(): PrVM[] {
  return site.github.prs.map((p) => ({
    title: p.title,
    url: p.url,
    number: p.number,
    repo: p.repo,
    repoUrl: p.repoUrl,
    repoStars: p.repoStars,
    owner: p.owner,
    avatar: p.avatar,
    own: p.own,
    status: p.status as PrStatus,
    date: (p.mergedAt || p.closedAt || p.createdAt).slice(0, 10),
    size: fmtSize(p.additions, p.deletions),
  }));
}

export function getPrStats() {
  const oss = getPrs().filter((p) => !p.own);
  return {
    total: oss.length,
    merged: oss.filter((p) => p.status === "merged").length,
    open: oss.filter((p) => p.status === "open").length,
    orgs: new Set(oss.map((p) => p.owner.toLowerCase())).size,
    topStars: Math.max(0, ...oss.map((p) => p.repoStars)),
  };
}

const FEATURED = new Set(["SentinelOps", "diffCraft"]);

export function getOtherRepos(): RepoVM[] {
  return site.github.repos
    .filter((r) => !FEATURED.has(r.name))
    .map((r) => ({
      name: r.name,
      description: r.description || REPO_DESCRIPTIONS[r.name] || "",
      url: r.url,
      homepage: r.homepage,
      language: r.language || "Docs",
      languageColor: r.languageColor,
      stars: r.stars,
      updatedAt: r.updatedAt.slice(0, 10),
    }));
}

export function getRepoCount() {
  return site.github.repos.length;
}

export function getCp(): CpVM {
  const lc = site.leetcode;
  const cf = site.codeforces;
  return {
    lc: {
      url: lc.url,
      username: lc.username,
      rating: lc.contest?.rating ?? null,
      badge: lc.contest?.badge ?? null,
      topPercentage: lc.contest?.topPercentage ?? null,
      attended: lc.contest?.attended ?? 0,
      solved: lc.solved as CpVM["lc"]["solved"],
      totals: lc.totals as CpVM["lc"]["totals"],
      history: lc.history,
    },
    cf: {
      url: cf.url,
      handle: cf.handle,
      rating: cf.rating,
      maxRating: cf.maxRating,
      rank: cf.rank,
      maxRank: cf.maxRank,
      solved: cf.solved,
      contests: cf.contests,
      history: cf.history.map(({ rating, date, contest }) => ({ rating, date, contest })),
    },
  };
}

export function getActivity(): ActivityVM {
  const c = site.github.contributions;
  return {
    total: c.total,
    commits: c.commits,
    pullRequests: c.pullRequests,
    privateContributions: c.privateContributions,
    start: c.start,
    end: c.end,
    weeks: c.weeks as [string, number, number][][],
  };
}

/** Rounded-down "N+" for headline copy, e.g. 561 → "550+". */
export const floorPlus = (n: number, step = 50) => `${Math.floor(n / step) * step}+`;

/** Compact facts for the command palette, terminal and boot sequence. */
export function getSummary() {
  const cp = getCp();
  const pr = getPrStats();
  return {
    solvedTotal: cp.lc.solved.all + cp.cf.solved,
    lcSolved: cp.lc.solved.all,
    lcRating: cp.lc.rating,
    lcBadge: cp.lc.badge,
    lcTop: cp.lc.topPercentage,
    cfRating: cp.cf.rating,
    cfMax: cp.cf.maxRating,
    cfSolved: cp.cf.solved,
    prTotal: pr.total,
    prMerged: pr.merged,
    prOrgs: pr.orgs,
    repos: getRepoCount(),
    contributions: site.github.contributions.total,
    ossRepos: [...new Set(getPrs().filter((p) => !p.own).map((p) => p.repo))],
    generatedAt: site.generatedAt,
  };
}
export type Summary = ReturnType<typeof getSummary>;
